{{-- Cláusula: OBJETO DEL CONTRATO. Fuentes: a.1 (base; a.1.2 pluraliza "LOS
     BIENES DESCRITOS"), a.1.6 (custodia: garantía mobiliaria CON POSESIÓN),
     a.1.4/a.1.3 (todos los bienes futuros: PRECONSTITUCIÓN + párrafo de bien
     futuro), a.1.5 (bien futuro y bien presente). Referencias cruzadas via
     $vm->ord->de('bien') / $vm->ord->de('valor'). --}}
@php
    $numsFuturos = [];
    $numsPresentes = [];
    foreach (array_values($vm->bienes) as $i => $b) {
        if (! empty($b['esFuturo'])) {
            $numsFuturos[] = $i + 1;
        } else {
            $numsPresentes[] = $i + 1;
        }
    }
    $plural = count($vm->bienes) > 1;
    $todosFuturos = $numsFuturos !== [] && $numsPresentes === [];
    $mixto = $numsFuturos !== [] && $numsPresentes !== [];
    // 'VEHICULO 1' / 'VEHICULOS 1 Y 2' (para el caso mixto, según a.1.5)
    $comoVehiculo = fn (array $nums) => (count($nums) > 1 ? 'VEHICULOS ' : 'VEHICULO ').implode(' Y ', $nums);
@endphp
<div class="clausula">
    <div class="clausula-titulo">{{ $vm->ord->de('objeto') }}: OBJETO DEL CONTRATO</div>

    @if ($vm->custodia)
        <p class="parrafo">EL PRESENTE CONTRATO TIENE POR OBJETO LA CONSTITUCIÓN DE UNA GARANTÍA MOBILIARIA CON POSESIÓN SOBRE {{ $plural ? 'LOS VEHÍCULOS DESCRITOS' : 'EL VEHÍCULO DESCRITO' }} EN LA CLÁUSULA {{ $vm->ord->de('bien') }}, EL CUAL ES ENTREGADO EN ESTE MISMO ACTO POR {{ $vm->g->deudor() }} A EL ACREEDOR EN CALIDAD DE DEPOSITARIO PARA SU CUSTODIA Y CONSERVACIÓN, DE CONFORMIDAD CON LO DISPUESTO EN EL DECRETO LEGISLATIVO N.° 1400 Y SU INSCRIPCIÓN EN EL SISTEMA INFORMATIVO DE GARANTÍAS MOBILIARIAS -SIGM ADMINISTRADO POR LA SUNARP, CON LA FINALIDAD DE GARANTIZAR EL CUMPLIMIENTO ÍNTEGRO Y OPORTUNO DE LA OBLIGACIÓN ESTABLECIDA EN LA CLÁUSULA {{ $vm->ord->de('valor') }} DEL PRESENTE CONTRATO, INCLUYENDO CAPITAL, INTERESES COMPENSATORIOS Y MORATORIOS, PENALIDADES, GASTOS ADMINISTRATIVOS, GASTOS DE CUSTODIA, CONSERVACIÓN, EJECUCIÓN Y CUALQUIER OTRO CONCEPTO DERIVADO DE LA RELACIÓN CONTRACTUAL. ASIMISMO, {{ $vm->g->deudor() }} {{ $vm->g->verbo('MANIFIESTA', 'MANIFIESTAN') }} DE MANERA EXPRESA E IRREVOCABLE SU VOLUNTAD DE CONSTITUIR LA PRESENTE GARANTÍA MOBILIARIA CON POSESIÓN A FAVOR DE EL ACREEDOR, ACEPTANDO EN TODOS SUS EXTREMOS LAS CONDICIONES Y ESTIPULACIONES CONTENIDAS EN EL PRESENTE CONTRATO.</p>
    @elseif ($todosFuturos)
